export {projects};
const words={en:{portfolio:'Our work',intro:'Commercial graphics and colour-change wraps from the Satin Auto Wrap portfolio.',all:'All projects',commercial:'Commercial wraps',colour:'Colour change',search:'Search projects',vehicle:'Vehicle',industry:'Industry',coverage:'Coverage',any:'All',photos:'photos',results:'projects',back:'Back to all work',prev:'Previous',next:'Next',view:'View project',quote:'Discuss a similar project',empty:'No projects match these filters.',photo:'Photo',clear:'Clear filters',details:'Project details',related:'More projects'},fa:{portfolio:'نمونه‌کارهای ما',intro:'پروژه‌های تبلیغات خودرو و تغییر رنگ از گالری Satin Auto Wrap.',all:'همه پروژه‌ها',commercial:'رپ تبلیغاتی',colour:'تغییر رنگ',search:'جستجوی پروژه‌ها',vehicle:'خودرو',industry:'صنعت',coverage:'پوشش',any:'همه',photos:'عکس',results:'پروژه',back:'بازگشت به نمونه‌کارها',prev:'قبلی',next:'بعدی',view:'مشاهده پروژه',quote:'درخواست پروژه مشابه',empty:'پروژه‌ای با این فیلترها پیدا نشد.',photo:'عکس',clear:'پاک کردن فیلترها',details:'اطلاعات پروژه',related:'پروژه‌های بیشتر'},fr:{portfolio:'Nos réalisations',intro:'Marquages commerciaux et changements de couleur du portfolio Satin Auto Wrap.',all:'Tous les projets',commercial:'Habillages commerciaux',colour:'Changement de couleur',search:'Rechercher des projets',vehicle:'Véhicule',industry:'Secteur',coverage:'Couverture',any:'Tous',photos:'photos',results:'projets',back:'Retour aux réalisations',prev:'Précédent',next:'Suivant',view:'Voir le projet',quote:'Discuter d’un projet similaire',empty:'Aucun projet ne correspond à ces filtres.',photo:'Photo',clear:'Effacer les filtres',details:'Détails du projet',related:'Autres projets'},es:{portfolio:'Nuestros trabajos',intro:'Rotulación comercial y cambios de color del portafolio de Satin Auto Wrap.',all:'Todos los proyectos',commercial:'Rotulación comercial',colour:'Cambio de color',search:'Buscar proyectos',vehicle:'Vehículo',industry:'Sector',coverage:'Cobertura',any:'Todos',photos:'fotos',results:'proyectos',back:'Volver a los trabajos',prev:'Anterior',next:'Siguiente',view:'Ver proyecto',quote:'Consultar un proyecto similar',empty:'Ningún proyecto coincide con estos filtros.',photo:'Foto',clear:'Borrar filtros',details:'Detalles del proyecto',related:'Más proyectos'}};
const vocab={'Commercial wrap':['رپ تبلیغاتی','Habillage commercial','Rotulación comercial'],'Colour change':['تغییر رنگ','Changement de couleur','Cambio de color'],Van:['ون','Fourgon','Furgoneta'],Truck:['کامیون / پیکاپ','Camion / pickup','Camión / pickup'],'Mini Van':['مینی‌ون','Minivan','Minivan'],Trailer:['تریلر','Remorque','Remolque'],SUV:['شاسی‌بلند','VUS','SUV'],Sedan:['سدان','Berline','Sedán'],Other:['سایر','Autre','Otros'],Construction:['ساخت‌وساز','Construction','Construcción'],Electric:['برق','Électricité','Electricidad'],Trading:['تجارت','Commerce','Comercio'],'Wood and Kitchen':['چوب و کابینت','Bois et cuisines','Madera y cocinas'],Plumbing:['لوله‌کشی','Plomberie','Fontanería'],HVAC:['تهویه مطبوع','Chauffage et climatisation','Climatización'],'Full Wrap':['رپ کامل','Habillage complet','Rotulación completa'],'Partial Wrap':['رپ جزئی','Habillage partiel','Rotulación parcial'],Decal:['برچسب','Autocollants','Vinilos']};
const label=(s,lang)=>lang==='en'?s:vocab[s]?.[['fa','fr','es'].indexOf(lang)]||s;
const base=lang=>'/satin'+(lang==='en'?'':'/'+lang);
const origin='https://satin-graphic-website.mehrad-tr.chatgpt.site';
const image=p=>p.cover||p.images[0];
function card(p,lang){const w=words[lang];return `<a class="portfolio-card" href="${base(lang)}/portfolio/projects/${p.slug}/"><div class="portfolio-card-photo"><img src="${image(p).thumb||image(p).src}" alt="${esc(image(p).alt)}" width="640" height="450" loading="lazy"><span>${p.images.length} ${w.photos}</span></div><div class="portfolio-card-info"><small>${p.category==='commercial'?w.commercial:w.colour}${p.vehicle?' · '+esc(label(p.vehicle,lang)):''}</small><h2>${esc(p.title)}</h2><div class="portfolio-tags">${p.tags.slice(0,3).map(t=>`<span>${esc(label(t,lang))}</span>`).join('')}</div><span class="portfolio-view">${w.view} ↗</span></div></a>`;}
export function portfolioPage(lang='en',path='/portfolio',query=new URLSearchParams(),records=projects){
const projects=records;const w=words[lang]||words.en,slug=path.split('/projects/')[1],p=slug?projects.find(p=>p.slug===slug):null,b=base(lang);if(slug&&!p)return null;
if(p){const category=p.category==='commercial'?w.commercial:w.colour;const html=`<section class="portfolio-project-hero"><div class="wrap"><nav class="portfolio-crumbs" aria-label="Breadcrumb"><a href="${b}/">Satin Graphic</a><span>/</span><a href="${b}/portfolio/">${w.portfolio}</a><span>/</span><span>${esc(p.title)}</span></nav><div class="portfolio-project-top"><div><span class="eyebrow">${category}</span><h1>${esc(p.title)}</h1><p>${description(p,lang)}</p><div class="portfolio-tags">${p.tags.map(t=>`<span>${esc(label(t,lang))}</span>`).join('')}</div></div><a class="btn" href="${b}/contact/">${w.quote}</a></div><figure><img src="${image(p).src}" alt="${esc(image(p).alt)}" width="${image(p).width}" height="${image(p).height}" fetchpriority="high"><figcaption>${esc(p.title)} · ${category}</figcaption></figure></div></section><section class="portfolio-project-details"><div class="wrap"><h2>${w.details}</h2><dl>${[[w.vehicle,p.vehicle||p.model],[w.industry,p.industry],[w.coverage,p.coverage]].filter(a=>a[1]).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(label(v,lang))}</dd></div>`).join('')}<div><dt>${w.photos}</dt><dd>${p.images.length}</dd></div></dl><div class="portfolio-project-photos">${p.images.map((im,i)=>`<figure><a href="${im.src}" target="_blank" rel="noopener"><img src="${im.src}" alt="${esc(im.alt)}" width="${im.width}" height="${im.height}" loading="lazy"></a><figcaption>${w.photo} ${i+1} · ${esc(p.title)}</figcaption></figure>`).join('')}</div><a href="${b}/portfolio/" class="btn ghost">${w.back}</a></div></section><section class="portfolio-related"><div class="wrap"><h2>${w.related}</h2><div class="portfolio-grid">${projects.filter(x=>x.id!==p.id&&x.category===p.category&&(x.vehicle===p.vehicle||x.model===p.model)).slice(0,3).map(x=>card(x,lang)).join('')}</div></div></section>`;return {title:p.title,html,portfolio:true,meta:{title:p.title+' · '+category+' | Satin Graphic',description:description(p,lang),image:image(p).src},record:p};}
const category=path==='/portfolio/commercial'?'commercial':path==='/portfolio/colour-change'?'colour':'',q=(query.get('q')||'').trim().toLowerCase(),vehicle=query.get('vehicle')||'',industry=query.get('industry')||'',coverage=query.get('coverage')||'';
const matches=projects.filter(p=>(!category||p.category===category)&&(!vehicle||p.vehicle===vehicle)&&(!industry||p.industry===industry)&&(!coverage||p.coverage===coverage)&&(!q||(p.title+' '+p.tags.join(' ')+' '+(p.model||'')).toLowerCase().includes(q)));const totalPages=Math.max(1,Math.ceil(matches.length/24)),number=Math.min(totalPages,Math.max(1,parseInt(query.get('page'))||1)),slice=matches.slice((number-1)*24,number*24),title=category==='commercial'?w.commercial:category==='colour'?w.colour:w.portfolio;
const options=(key,title)=>`<label>${title}<select name="${key}"><option value="">${w.any}</option>${[...new Set(projects.map(p=>p[key]).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${v===query.get(key)?'selected':''}>${esc(label(v,lang))}</option>`).join('')}</select></label>`;
const pageHref=n=>{const qs=new URLSearchParams(query);qs.set('page',n);return b+path+'/?'+qs.toString();};
const html=`<section class="portfolio-intro"><div class="wrap"><span class="eyebrow">Satin Auto Wrap × Satin Graphic</span><div class="portfolio-intro-top"><h1>${title}</h1><p>${w.intro}</p></div><nav class="portfolio-categories" aria-label="${w.portfolio}">${[['',w.all],['/commercial',w.commercial],['/colour-change',w.colour]].map(([s,t])=>`<a ${path==='/portfolio'+s?'aria-current="page"':''} href="${b}/portfolio${s}/">${t}<small>${projects.filter(p=>!s||p.category===(s==='/commercial'?'commercial':'colour')).length}</small></a>`).join('')}</nav></div></section><section class="portfolio-results"><div class="wrap"><form class="portfolio-filters" data-portfolio-filter action="${b+path}/" method="get"><label class="portfolio-search">${w.search}<input type="search" name="q" value="${esc(query.get('q')||'')}" placeholder="${w.search}"></label>${options('vehicle',w.vehicle)}${options('industry',w.industry)}${options('coverage',w.coverage)}<button class="btn sm" type="submit">${w.search}</button><a href="${b+path}/">${w.clear}</a></form><div class="portfolio-count"><span>${matches.length} ${w.results}</span><span>${number} / ${totalPages}</span></div><div class="portfolio-grid">${slice.map(p=>card(p,lang)).join('')}</div>${!matches.length?`<p class="portfolio-no-results">${w.empty}</p>`:''}<nav class="portfolio-pagination" aria-label="Pagination">${number>1?`<a class="btn ghost" href="${pageHref(number-1)}">${w.prev}</a>`:''}${Array.from({length:totalPages},(_,i)=>i+1).filter(n=>n===1||n===totalPages||Math.abs(n-number)<=2).map(n=>`<a href="${pageHref(n)}" ${n===number?'aria-current="page"':''}>${n}</a>`).join('')}${number<totalPages?`<a class="btn ghost" href="${pageHref(number+1)}">${w.next}</a>`:''}</nav></div></section>`;
return {title,html,portfolio:true,meta:{title:title+' · Vehicle wrap portfolio | Satin Graphic',description:w.intro,image:image(slice[0]||projects[0]).src,noindex:!!(q||vehicle||industry||coverage)},listing:slice,page:number};
}
function description(p,lang){if(p.description)return esc(p.description);const specs=[p.vehicle||p.model,p.coverage,p.industry].filter(Boolean).map(s=>label(s,lang)).join(' · ');return ({en:`${p.title} — ${p.category==='commercial'?'commercial vehicle graphics':'colour-change wrap'} by Satin Auto Wrap. ${specs}. Explore the finished project and its photos.`,fa:`${p.title} — ${p.category==='commercial'?'رپ تبلیغاتی خودرو':'رپ تغییر رنگ'} توسط Satin Auto Wrap. ${specs}. تصاویر کامل پروژه را ببینید.`,fr:`${p.title} — ${p.category==='commercial'?'marquage de véhicule commercial':'changement de couleur'} par Satin Auto Wrap. ${specs}. Découvrez les photos du projet terminé.`,es:`${p.title} — ${p.category==='commercial'?'rotulación de vehículo comercial':'cambio de color'} de Satin Auto Wrap. ${specs}. Descubre las fotos del proyecto terminado.`})[lang];}
export function portfolioSEO(lang,path,page,query=new URLSearchParams()){
const canonical=origin+base(lang)+path+'/' +(page.page>1&&!page.meta.noindex?'?page='+page.page:''),im=origin+page.meta.image;const graph=[{'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Satin Graphic',item:origin+base(lang)+'/'},{'@type':'ListItem',position:2,name:words[lang].portfolio,item:origin+base(lang)+'/portfolio/'},...(page.record?[{'@type':'ListItem',position:3,name:page.record.title,item:canonical}]:[])]}];if(page.record){const p=page.record;graph.push({'@type':'CreativeWork',name:p.title,description:page.meta.description,url:canonical,creator:{'@type':'Organization',name:'Satin Auto Wrap'},keywords:p.tags.join(', '),image:p.images.map(i=>({'@type':'ImageObject',contentUrl:origin+i.src,caption:i.alt,width:i.width,height:i.height}))});}else graph.push({'@type':'CollectionPage',name:page.title,url:canonical,description:page.meta.description,mainEntity:{'@type':'ItemList',itemListElement:page.listing.map((p,i)=>({'@type':'ListItem',position:(page.page-1)*24+i+1,name:p.title,url:origin+base(lang)+'/portfolio/projects/'+p.slug+'/'}))}});return {...page.meta,canonical,image:im,jsonld:{'@context':'https://schema.org','@graph':graph}};}
export function mountPortfolio(root,navigate){const form=root.querySelector('[data-portfolio-filter]');if(form){form.addEventListener('submit',e=>{e.preventDefault();const url=new URL(form.action,location.origin);for(const [k,v]of new FormData(form))if(v)url.searchParams.set(k,v);navigate(url);});form.querySelectorAll('select').forEach(s=>s.addEventListener('change',()=>form.requestSubmit()));}}